import FreeCAD
import Part

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")
sketch = doc.getObject("Sketch")

# Get all geometry and print detailed info
print("=== GEOMETRY DETAILS ===")
for i, geo in enumerate(sketch.Geometry):
    print(f"\nGeometry {i}: {geo.TypeId}")
    if hasattr(geo, 'Base'):
        print(f"  Base: {geo.Base}")
    if hasattr(geo, 'Radius'):
        print(f"  Radius: {geo.Radius}")
    if hasattr(geo, 'StartParameter') and hasattr(geo, 'EndParameter'):
        print(f"  StartParam: {geo.StartParameter}, EndParam: {geo.EndParameter}")
    # Try to get endpoints
    try:
        shape = geo.toShape()
        if shape.ShapeType == "Edge":
            print(f"  Vertex0: {shape.Vertexes[0].Point}")
            print(f"  Vertex1: {shape.Vertexes[-1].Point}")
    except:
        pass

# Print constraint summary
print("\n\n=== CONSTRAINT SUMMARY ===")
constraint_types = {}
for c in sketch.Constraints:
    t = c.Type
    constraint_types[t] = constraint_types.get(t, 0) + 1
for t, count in sorted(constraint_types.items()):
    print(f"{t}: {count}")

FreeCAD.closeDocument(doc.Name)
