{"script": "cat > /tmp/copy_sketch.py << 'EOF'
import FreeCAD
import Part
import Sketcher

# Open the precondition file
doc_pre = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")
sketch_pre = doc_pre.getObject("Sketch")

# Create a new document
doc = FreeCAD.newDocument("Unnamed")

# Create a new sketch
sketch = doc.addObject("Sketcher::SketchObject", "Sketch")

# Copy geometry from precondition
for geo in sketch_pre.Geometry:
    # Get the underlying shape and recreate
    if hasattr(geo, 'toShape'):
        shape = geo.toShape()
        curve = shape.Curve

        if curve.TypeId == "Part::GeomCircle":
            new_geo = Part.Circle(curve.Center, curve.Axis, curve.Radius)
            sketch.addGeometry(new_geo, False)  # False = don't move to new position
        elif curve.TypeId == "Part::GeomLineSegment":
            v1 = curve.StartPoint
            v2 = curve.EndPoint
            new_geo = Part.LineSegment(v1, v2)
            sketch.addGeometry(new_geo, False)
        else:
            print(f"Unknown curve type: {curve.TypeId}")

print(f"Copied {len(sketch.Geometry)} geometries")

# Now copy constraints
for c in sketch_pre.Constraints:
    try:
        if c.Type == 'Radius':
            sketch.addConstraint(Sketcher.Constraint('Radius', c.First, c.Value))
        elif c.Type == 'PointOnObject':
            sketch.addConstraint(Sketcher.Constraint('PointOnObject', c.First, c.Second, c.Value))
        elif c.Type == 'Tangent':
            sketch.addConstraint(Sketcher.Constraint('Tangent', c.First, c.Second))
        elif c.Type == 'Coincident':
            sketch.addConstraint(Sketcher.Constraint('Coincident', c.First, c.Second))
        elif c.Type == 'DistanceY':
            sketch.addConstraint(Sketcher.Constraint('DistanceY', c.First, c.Second, c.Value))
        elif c.Type == 'Horizontal':
            sketch.addConstraint(Sketcher.Constraint('Horizontal', c.First))
        elif c.Type == 'Equal':
            sketch.addConstraint(Sketcher.Constraint('Equal', c.First, c.Second))
        elif c.Type == 'Vertical':
            sketch.addConstraint(Sketcher.Constraint('Vertical', c.First))
        elif c.Type == 'DistanceX':
            sketch.addConstraint(Sketcher.Constraint('DistanceX', c.First, c.Second, c.Value))
        else:
            print(f"Unknown constraint type: {c.Type}")
    except Exception as e:
        print(f"Error adding constraint: {e}, Type={c.Type}, First={c.First}, Second={c.Second}")

print(f"Added {len(sketch.Constraints)} constraints")

FreeCAD.ActiveDocument.recompute()

# Check if sketch is valid
try:
    shape = sketch.Shape
    print(f"Sketch shape type: {shape.ShapeType}")
    print(f"Number of edges in shape: {len(shape.Edges)}")
except Exception as e:
    print(f"Error creating shape: {e}")

doc.saveAs("/home/user/Unnamed.FCStd")
print("Saved to /home/user/Unnamed.FCStd")

FreeCAD.closeDocument(doc_pre.Name)
FreeCAD.closeDocument(doc.Name)
EOF
